import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Alert from '../../components/Alert';
import Card from '../../components/Card';
import Field from '../../components/Field';
import PageHeader from '../../components/PageHeader';
import { registerStudent } from '../../services/studentService';

/**
 * UC02 register student. The number, the institutional email and the initial password
 * are generated by the system.
 */
export default function RegisterStudentPage() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    name: '',
    firstEnrolmentYear: new Date().getFullYear(),
    entryGrade: ''
  });
  const [fieldErrors, setFieldErrors] = useState({});
  const [error, setError] = useState('');
  const [registered, setRegistered] = useState(null);
  const [saving, setSaving] = useState(false);

  function updateField(name, value) {
    setForm({ ...form, [name]: value });
  }

  async function handleSubmit(event) {
    event.preventDefault();
    setError('');
    setFieldErrors({});
    setSaving(true);
    try {
      const result = await registerStudent({
        name: form.name,
        firstEnrolmentYear: Number(form.firstEnrolmentYear),
        entryGrade: form.entryGrade === '' ? null : Number(form.entryGrade)
      });
      setRegistered(result);
    } catch (registerError) {
      setError(registerError.message);
      setFieldErrors(registerError.fieldErrors || {});
    } finally {
      setSaving(false);
    }
  }

  if (registered) {
    const student = registered;
    const { initialPassword } = registered;
    return (
      <div className="page">
        <PageHeader title="Estudante registado." subtitle="A conta institucional foi criada." />
        <Card title={student.name}>
          <div className="detail-list">
            <span>
              <strong>Número:</strong> {student.number}
            </span>
            <span>
              <strong>Email institucional:</strong> {student.email}
            </span>
            <span>
              <strong>Palavra-passe inicial:</strong> <code>{initialPassword}</code>
            </span>
          </div>
          <Alert type="warning">
            A palavra-passe inicial só é mostrada agora. Entrega-a ao estudante.
          </Alert>
          <div className="form-actions">
            <button
              type="button"
              className="button button--primary"
              onClick={() => navigate(`/admin/students/${student.id}`)}
            >
              Ver ficha →
            </button>
            <button type="button" className="button" onClick={() => setRegistered(null)}>
              Registar outro
            </button>
          </div>
        </Card>
      </div>
    );
  }

  return (
    <div className="page">
      <PageHeader
        title="Cada percurso começa aqui."
        subtitle="Cria a identidade académica e a conta institucional de um estudante."
      />

      <Card title="Identidade académica">
        <form className="form" onSubmit={handleSubmit} noValidate>
          <Field label="Nome completo" error={fieldErrors.name}>
            <input
              className={`input ${fieldErrors.name ? 'input--invalid' : ''}`}
              placeholder="Nome e apelido"
              value={form.name}
              onChange={(event) => updateField('name', event.target.value)}
            />
          </Field>
          <div className="form-row">
            <Field label="Número de estudante · automático">
              <input className="input" value="Gerado automaticamente ao criar" disabled />
            </Field>
            <Field label="Primeira inscrição" error={fieldErrors.firstEnrolmentYear}>
              <input
                className="input"
                type="number"
                value={form.firstEnrolmentYear}
                onChange={(event) => updateField('firstEnrolmentYear', event.target.value)}
              />
            </Field>
          </div>
          <Field label="Email institucional">
            <input className="input" value="numero@studymatch.com" disabled />
          </Field>
          <div className="form-row">
            <Field label="Nota de ingresso · opcional" error={fieldErrors.entryGrade}>
              <input
                className={`input ${fieldErrors.entryGrade ? 'input--invalid' : ''}`}
                type="number"
                placeholder="0 a 200"
                value={form.entryGrade}
                onChange={(event) => updateField('entryGrade', event.target.value)}
              />
            </Field>
          </div>
          <p className="small muted">
            O número segue a sequência única 1, 2, 3… partilhada por alunos e docentes. O email é
            numero@studymatch.com.
          </p>

          {error && <Alert type="danger">{error}</Alert>}

          <div className="form-actions">
            <button type="submit" className="button button--primary" disabled={saving}>
              {saving ? 'A criar…' : 'Criar estudante →'}
            </button>
            <Link to="/admin/students" className="button">
              Cancelar
            </Link>
          </div>
        </form>
      </Card>
    </div>
  );
}
